for ref in REFS:
    ref.update({"subject": "science", "locator": ref["title"] + "；整份試卷／資源頁的氣候與生態判讀題型", "observedPattern": "研究公立學校公開試題、課綱與教育雲資料中的氣候變化、生物分布、物候、棲地壓力、調查設計與適應管理方向；未複製原題文字、選項、圖表或答案。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"})
for i, (prompt, options, answer, explanation, strategy) in enumerate(DATA, 1):
    path = ROOT / "questions/science" / f"question-science-content-nb-iv-1-{i}.json"
    item = json.loads(path.read_text())
    correct = options[ord(answer) - 65]
    target_letters=["A", "B", "C", "D", "B", "C", "D", "A", "C", "B"]
    target=target_letters[i-1]
    distractors=[t for t in options if t != correct]
    ordered=[]; di=0
    for letter in ["A", "B", "C", "D"]:
        if letter == target: ordered.append(correct)
        else: ordered.append(distractors[di]); di += 1
    item.update({"prompt": prompt, "options": [{"id": chr(65+j), "text": t} for j, t in enumerate(ordered)], "answer": {"value": target, "explanation": f"{explanation} 正確答案為選項 {target}：「{correct}」。"}, "solutionStrategy": strategy, "solutionSteps": ["圈出氣候變因、生物反應、時間尺度、空間尺度與對照資料。", "檢查是否有長期資料、標準化調查與足夠的替代解釋控制。", f"套用本題原理：{explanation}", f"排除把單次觀察當因果、忽略延遲或過度外推的選項，答案為「{correct}」。", "回查結論是否同時考慮自然變異、其他壓力與適應管理的可調整性。"], "examPatternRefs": REFS, "reviewStatus": "draft"})
    path.write_text(json.dumps(item, ensure_ascii=False, indent=2) + "\n")
print(f"rewrote {len(DATA)} questions")
